+/**
+ * Disclosure Widget - Accessible collapsible content
+ * 
+ * Implements WCAG 2.2 AA disclosure pattern:
+ * - Adds `hidden` attribute to collapsed panels at init
+ * - Ensures content is visible in reader mode and no-JS environments
+ * - Manages aria-expanded state
+ * - Supports Space and Enter key activation
+ * - Optional Escape key to collapse (returns focus to trigger)
+ */
+
+document.addEventListener('DOMContentLoaded', () => {
+    initializeDisclosureWidgets();
+});
+
+function initializeDisclosureWidgets() {
+    const triggers = document.querySelectorAll('button[aria-expanded]');
+
+    triggers.forEach((button) => {
+        // Get the panel (next sibling div with class "details")
+        const panel = button.closest('h3')?.nextElementSibling;
+
+        if (!panel || !panel.classList.contains('details')) {
+            console.warn('Disclosure widget: panel not found for button', button);
+            return;
+        }
+
+        // Initialize collapsed state
+        button.setAttribute('aria-expanded', 'false');
+        panel.hidden = true;
+
+        // Click handler
+        button.addEventListener('click', () => {
+            toggleDisclosure(button, panel);
+        });
+
+        // Keyboard support
+        button.addEventListener('keydown', (event) => {
+            if (event.key === 'Enter' || event.key === ' ') {
+                event.preventDefault();
+                toggleDisclosure(button, panel);
+            } else if (event.key === 'Escape') {
+                const isOpen = button.getAttribute('aria-expanded') === 'true';
+                if (isOpen) {
+                    event.preventDefault();
+                    collapseDisclosure(button, panel);
+                    button.focus();
+                }
+            }
+        });
+    });
+}
+
+function toggleDisclosure(button, panel) {
+    const isOpen = button.getAttribute('aria-expanded') === 'true';
+
+    if (isOpen) {
+        collapseDisclosure(button, panel);
+    } else {
+        expandDisclosure(button, panel);
+    }
+}
+
+function expandDisclosure(button, panel) {
+    button.setAttribute('aria-expanded', 'true');
+    panel.hidden = false;
+}
+
+function collapseDisclosure(button, panel) {
+    button.setAttribute('aria-expanded', 'false');
+    panel.hidden = true;
+}
+
